-- 1) Supprime l'import Excel "brouillon" (mois non renseigné) et ses opérations,
--    pour ne garder qu'un seul import "officiel" pour juin 2026 (le PDF ci-dessous).
delete from operations_bancaires
where import_id in (
  select id from imports
  where type_import = 'banque' and mois is null and nom_fichier = 'CA20260710_183248.xlsx'
);

delete from imports
where type_import = 'banque' and mois is null and nom_fichier = 'CA20260710_183248.xlsx';

-- 2) Import officiel de juin 2026
with nouveaux_imports as (
  insert into imports (exercice_id, type_import, mois, nom_fichier, statut)
  select e.id, 'banque', v.mois, v.nom_fichier, 'importé'
  from (values
  ('2026-06', 'Relevé n°006 du 30-06-2026_CCOU 87005854626 EURL GEMVAP.pdf')
  ) as v(mois, nom_fichier)
  join exercices e on to_date(v.mois || '-01', 'YYYY-MM-DD') between e.date_debut and e.date_fin
  returning id, mois
)
